<?php
if(!defined('ABSPATH'))exit;
function eicr_smtp_encrypt($value){if($value==='')return'';if(!function_exists('openssl_encrypt'))return'plain:'.base64_encode($value);$key=hash('sha256',wp_salt('auth'),true);$iv=random_bytes(16);$cipher=openssl_encrypt($value,'AES-256-CBC',$key,OPENSSL_RAW_DATA,$iv);return'enc:'.base64_encode($iv.$cipher);}
function eicr_smtp_decrypt($value){if(!$value)return'';if(str_starts_with($value,'plain:'))return(string)base64_decode(substr($value,6),true);if(!str_starts_with($value,'enc:')||!function_exists('openssl_decrypt'))return'';$raw=base64_decode(substr($value,4),true);if($raw===false||strlen($raw)<=16)return'';$key=hash('sha256',wp_salt('auth'),true);return(string)openssl_decrypt(substr($raw,16),'AES-256-CBC',$key,OPENSSL_RAW_DATA,substr($raw,0,16));}
function eicr_smtp_settings(){return wp_parse_args((array)get_option('eicr_smtp_settings',[]),['enabled'=>0,'host'=>'','port'=>587,'encryption'=>'tls','auth'=>1,'username'=>'','password'=>'','from_email'=>'','from_name'=>'EICR in London']);}
add_action('admin_menu',function(){add_submenu_page('eicr-control','Email & SMTP','Email & SMTP','manage_options','eicr-smtp','eicr_smtp_admin_page');},20);
function eicr_smtp_admin_page(){if(!current_user_can('manage_options'))return;$o=eicr_smtp_settings();$notice=sanitize_key($_GET['smtp_notice']??'');$detail=get_transient('eicr_smtp_notice_'.get_current_user_id());if($detail)delete_transient('eicr_smtp_notice_'.get_current_user_id());echo'<div class="wrap eicr-admin-wrap"><h1>Email & SMTP</h1><p>Send booking confirmations, invoices, quote notifications and test messages through your authenticated mail provider.</p>';if($notice)echo'<div class="notice '.($notice==='sent'?'notice-success':'notice-error').' is-dismissible"><p>'.esc_html($detail?:($notice==='sent'?'Test email sent successfully.':'Email could not be sent. Check the settings and try again.')).'</p></div>';echo'<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="eicr_save_smtp">';wp_nonce_field('eicr_save_smtp');echo'<table class="form-table"><tr><th>Enable SMTP</th><td><label><input type="checkbox" name="enabled" value="1" '.checked(!empty($o['enabled']),true,false).'> Route WordPress email through this SMTP server</label></td></tr>';eicr_smtp_row('host','SMTP host',$o['host'],'text','Example: smtp.gmail.com');eicr_smtp_row('port','SMTP port',$o['port'],'number','Usually 587 for TLS or 465 for SSL');echo'<tr><th><label for="encryption">Encryption</label></th><td><select id="encryption" name="encryption"><option value="tls" '.selected($o['encryption'],'tls',false).'>TLS</option><option value="ssl" '.selected($o['encryption'],'ssl',false).'>SSL</option><option value="none" '.selected($o['encryption'],'none',false).'>None</option></select></td></tr><tr><th>Authentication</th><td><label><input type="checkbox" name="auth" value="1" '.checked(!empty($o['auth']),true,false).'> SMTP username and password required</label></td></tr>';eicr_smtp_row('username','SMTP username',$o['username'],'text','Usually the full email address');eicr_smtp_row('password','SMTP password','','password',$o['password']?'Saved securely. Leave blank to keep the current password.':'Use an app password where your provider requires one.');eicr_smtp_row('from_email','From email',$o['from_email'],'email','Must normally match the authenticated mailbox or an approved sender.');eicr_smtp_row('from_name','From name',$o['from_name'],'text','Shown to customers as the sender name.');echo'</table>';submit_button('Save SMTP settings');echo'</form><hr><h2>Send a test email</h2><p>Save the SMTP settings first, then send a real test message.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="eicr-smtp-test"><input type="hidden" name="action" value="eicr_test_smtp">';wp_nonce_field('eicr_test_smtp');echo'<label for="test_email"><strong>Test recipient</strong></label> <input class="regular-text" type="email" id="test_email" name="test_email" value="'.esc_attr(wp_get_current_user()->user_email).'" required> ';submit_button('Send Test Email','secondary','submit',false);echo'</form><p class="description"><strong>Gmail:</strong> smtp.gmail.com, port 587, TLS, authentication enabled, full Gmail address as username, and a Google App Password.</p></div>';}
function eicr_smtp_row($key,$label,$value,$type='text',$help=''){echo'<tr><th><label for="'.esc_attr($key).'">'.esc_html($label).'</label></th><td><input class="regular-text" type="'.esc_attr($type).'" id="'.esc_attr($key).'" name="'.esc_attr($key).'" value="'.esc_attr($value).'">'.($help?'<p class="description">'.esc_html($help).'</p>':'').'</td></tr>';}
add_action('admin_post_eicr_save_smtp',function(){if(!current_user_can('manage_options'))wp_die('Not allowed.');check_admin_referer('eicr_save_smtp');$old=eicr_smtp_settings();$encryption=sanitize_key(wp_unslash($_POST['encryption']??'tls'));if(!in_array($encryption,['tls','ssl','none'],true))$encryption='tls';$port=absint($_POST['port']??587);if($port<1||$port>65535)$port=587;$password=isset($_POST['password'])&&!is_array($_POST['password'])?(string)wp_unslash($_POST['password']):'';$settings=['enabled'=>!empty($_POST['enabled'])?1:0,'host'=>sanitize_text_field(wp_unslash($_POST['host']??'')),'port'=>$port,'encryption'=>$encryption,'auth'=>!empty($_POST['auth'])?1:0,'username'=>sanitize_text_field(wp_unslash($_POST['username']??'')),'password'=>$password!==''?eicr_smtp_encrypt($password):$old['password'],'from_email'=>sanitize_email(wp_unslash($_POST['from_email']??'')),'from_name'=>sanitize_text_field(wp_unslash($_POST['from_name']??'EICR in London'))];update_option('eicr_smtp_settings',$settings,false);wp_safe_redirect(admin_url('admin.php?page=eicr-smtp'));exit;});
add_action('phpmailer_init',function($mailer){$o=eicr_smtp_settings();if(empty($o['enabled'])||empty($o['host']))return;$mailer->isSMTP();$mailer->Host=$o['host'];$mailer->Port=(int)$o['port'];$mailer->SMTPAuth=!empty($o['auth']);$mailer->Timeout=20;$mailer->SMTPDebug=0;if($o['encryption']==='tls')$mailer->SMTPSecure='tls';elseif($o['encryption']==='ssl')$mailer->SMTPSecure='ssl';else{$mailer->SMTPSecure='';$mailer->SMTPAutoTLS=false;}if($mailer->SMTPAuth){$mailer->Username=$o['username'];$mailer->Password=eicr_smtp_decrypt($o['password']);}if(is_email($o['from_email'])){$mailer->From=$o['from_email'];$mailer->Sender=$o['from_email'];}$mailer->FromName=$o['from_name']?:'EICR in London';});
add_action('admin_post_eicr_test_smtp',function(){if(!current_user_can('manage_options'))wp_die('Not allowed.');check_admin_referer('eicr_test_smtp');$to=sanitize_email(wp_unslash($_POST['test_email']??''));if(!is_email($to)){set_transient('eicr_smtp_notice_'.get_current_user_id(),'Enter a valid test recipient email.',60);wp_safe_redirect(admin_url('admin.php?page=eicr-smtp&smtp_notice=failed'));exit;}$error='';$listener=function($wp_error)use(&$error){$error=$wp_error->get_error_message();};add_action('wp_mail_failed',$listener);$sent=wp_mail($to,'EICR in London SMTP test','This test confirms that your WordPress SMTP mail delivery is working. Website: '.home_url('/'),['Content-Type: text/plain; charset=UTF-8']);remove_action('wp_mail_failed',$listener);$message=$sent?'Test email sent to '.$to.'. Check the inbox and spam folder.':('Test failed'.($error?': '.$error:'. Check SMTP host, port, encryption, username and password.'));set_transient('eicr_smtp_notice_'.get_current_user_id(),$message,120);wp_safe_redirect(admin_url('admin.php?page=eicr-smtp&smtp_notice='.($sent?'sent':'failed')));exit;});
